<?php
declare(strict_types=1);
$root=$argv[1];
spl_autoload_register(function(string $class)use($root):void{$prefix='Sokna\\PublicEdge\\';if(str_starts_with($class,$prefix)){$p=$root.'/public/src/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($p))require_once $p;}});
require $root.'/public/src/Shared/IranTime.php';
$pdo=new PDO('mysql:host=127.0.0.1;port='.(getenv('DB_PORT')?:3306).';dbname=r83_public;charset=utf8mb4','root',getenv('DB_PASSWORD')?:'r83-test',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
(new Sokna\PublicEdge\Core\Migrations($pdo,$root.'/public/database/migrations'))->migrate();
$pdo->exec("INSERT INTO installations(installation_id,display_name) VALUES('r83-test','R83')");
$service=new Sokna\PublicEdge\Remote\RemoteReadModelService($pdo,new Sokna\PublicEdge\Connectivity\ConnectivityService($pdo));
$verifier=new Sokna\PublicEdge\Security\SignedLocalRequestVerifier($pdo,['r83-test'=>'r83-secret']);
$results=[];
function check(bool $v,string $name):void{global $results;$results[]=['test'=>$name,'pass'=>$v];if(!$v)throw new RuntimeException($name);}
$payload=['rows'=>array_fill(0,800,['name'=>'قهوه سکنا','status'=>'active','price'=>120000,'description'=>str_repeat('نمونه ',12)])];
$model=['format'=>'sokna-remote-read-v1','model_key'=>'reports','source_version'=>Sokna\PublicEdge\Core\CanonicalJson::sha256($payload),'generated_at'=>gmdate('c'),'payload'=>$payload];
$body=['format'=>'sokna-read-model-v2','up_to_sequence'=>1,'model'=>$model];
$response=$service->syncModelV2('r83-test',$body);
check($response['status']===200,'legacy uncompressed model still accepted');
$packed=['format'=>'sokna-read-model-v2','up_to_sequence'=>2,'authority_epoch'=>1,'model_encoding'=>'gzip-base64-v1','model_gzip'=>base64_encode(gzencode(json_encode($model,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),6))];
$wire=json_encode($packed,JSON_UNESCAPED_SLASHES);$path='/api/v1/local/read-model-v2';$ts=(string)time();$nonce=bin2hex(random_bytes(16));
$sig=$verifier->sign('r83-secret','POST',$path,$ts,$nonce,$wire);
$verified=$verifier->verify('r83-test','POST',$path,$ts,$nonce,$wire,$sig);
check($verified['ok']===true,'compressed wire verified before decompression');
check(!$verifier->verify('r83-test','POST',$path,$ts,bin2hex(random_bytes(16)),$wire.' ',$sig)['ok'],'altered compressed wire signature rejected');
$response=$service->syncModelV2('r83-test',$packed);
check($response['status']===200&&$response['body']['ack_sequence']===2,'compressed model stored with exact sequence');
check(strlen($wire)<strlen(json_encode($body,JSON_UNESCAPED_UNICODE))/2,'large repetitive snapshot wire reduced by more than half');
$stored=$pdo->query("SELECT payload_json FROM remote_read_models WHERE model_key='reports'")->fetchColumn();
check(json_decode($stored,true)===$payload,'decompression preserves complete business payload');
$replay=$service->syncModelV2('r83-test',$packed);check($replay['status']===200&&!empty($replay['body']['duplicate']),'lost compressed ACK safely replays');
$bad=$packed;$bad['model_gzip']='!invalid';check($service->syncModelV2('r83-test',$bad)['status']===422,'invalid base64 rejected');
$bad=$packed;$m=$model;$m['payload']['rows'][0]['price']=1;$bad['model_gzip']=base64_encode(gzencode(json_encode($m)));check($service->syncModelV2('r83-test',$bad)['status']===422,'canonical hash still rejects altered business content');
$bad=$packed;$bad['model_gzip']=base64_encode(gzencode(str_repeat('x',2097154)));check($service->syncModelV2('r83-test',$bad)['status']===413,'bounded decompression rejects oversized output');
$bad=$packed;$bad['model']=$model;check($service->syncModelV2('r83-test',$bad)['status']===422,'ambiguous compressed and uncompressed model rejected');
$old=$body;$old['model']['payload']=['old'=>true];$old['model']['source_version']=Sokna\PublicEdge\Core\CanonicalJson::sha256($old['model']['payload']);
$resp=$service->syncModelV2('r83-test',$old);check($resp['status']===409&&$resp['body']['error']==='projection_model_sequence_conflict','older delivery cannot roll back Public cursor');
check(json_decode($pdo->query("SELECT payload_json FROM remote_read_models WHERE model_key='reports'")->fetchColumn(),true)===$payload,'older delivery cannot replace newer Public content');
$session=['installation_id'=>'r83-test','capabilities'=>['reports.read']];
check($service->read($session,'reports')['status']===200,'Public report remains readable with Local offline');
check($service->read(['installation_id'=>'r83-test','capabilities'=>[]],'reports')['status']===403,'Public role guard remains enforced');
$pdo->exec("UPDATE remote_read_models SET payload_json='null' WHERE model_key='reports'");
check($service->read($session,'reports')['status']===502,'invalid stored report is not empty success');
echo json_encode(['tests'=>$results,'native_bytes'=>strlen(json_encode($body,JSON_UNESCAPED_UNICODE)),'encoded_bytes'=>strlen($wire)],JSON_PRETTY_PRINT).PHP_EOL;
